pub(crate) fn comptime_held_named(name: String, args: Vec<Ty>, view: bool, held: &BuildValue) -> Option<Ty> {
    match held {
        BuildValue::Text(_) => { if name == "String" && args.is_empty() { return Some(Ty::Named { name, args, view: true }); } },
        BuildValue::List(items) => {
            if name == "Vec" && args.len() == 1 {
                let element = match items.is_empty() {
                    true => (*nikaia_std::index::get(&args, 0)).clone(),
                    false => match comptime_held_as((*nikaia_std::index::get(&args, 0)).clone(), nikaia_std::index::get(&items, 0)) { Some(__nikaia_value) => __nikaia_value, None => return None },
                };
                return Some(Ty::Named { name: String::from("Array"), args: vec![element, Ty::Count(items.len() as i64)], view });
            }
        },
        _ => { },
    }
    Some(Ty::Named { name, args, view })
}

pub(crate) fn comptime_held_wide(n: &Integer) -> Option<Ty> {
    if n.magnitude <= 9223372036854775807u64 { return Some(Ty::Unknown); }
    if !n.negative { return Some(Ty::Named { name: String::from("u64"), args: vec![], view: false }); }
    if n.magnitude == 9223372036854775808u64 { return Some(Ty::Unknown); }
    None
}

